{
  "$schema": "https://pets.studio/config.json",
  "name": "@openpets/anthropic",
  "version": "1.0.4",
  "title": "Anthropic",
  "subtitle": "Interact with Claude AI via the Anthropic API",
  "description": "OpenPets plugin for the Anthropic API. Create messages, manage batches, count tokens, and manage your organization with Admin API. Includes organization management, workspace control, usage/cost reports, and more.",
  "homepage": "https://www.anthropic.com",
  "categories": [
    "ai",
    "developer-tools"
  ],
  "main": "index.ts",
  "types": "index.ts",
  "keywords": [
    "opencode",
    "openpets",
    "plugin",
    "anthropic",
    "claude",
    "ai",
    "llm"
  ],
  "providers": [
    {
      "id": "anthropic",
      "name": "Anthropic",
      "credentialsUrl": "https://console.anthropic.com/settings/keys"
    }
  ],
  "envVariables": {
    "required": [
      {
        "name": "ANTHROPIC_API_KEY",
        "description": "API key for Anthropic API (standard Claude access)",
        "providerId": "anthropic",
        "priority": 1
      }
    ],
    "optional": [
      {
        "name": "ANTHROPIC_ADMIN_API_KEY",
        "description": "Admin API key for organization/workspace management (starts with sk-ant-admin...)",
        "providerId": "anthropic",
        "priority": 2
      },
      {
        "name": "ANTHROPIC_VERSION",
        "description": "API version header (defaults to 2023-06-01)",
        "providerId": "anthropic",
        "priority": 3
      }
    ]
  },
  "queries": [
    "test anthropic connection",
    "test admin connection",
    "send a message to Claude asking what is the capital of France",
    "count tokens in a prompt",
    "list message batches",
    "get batch status for batch_123",
    "ask Claude to explain recursion in simple terms",
    "list all organization members",
    "list all workspaces",
    "get usage report for last 7 days",
    "get cost report for January 2025",
    "list all API keys",
    "list all skills",
    "list custom skills only",
    "create a new skill for code review"
  ],
  "scenarios": {
    "connection-test": [
      "test anthropic connection",
      "test admin connection"
    ],
    "simple-message": [
      "test anthropic connection",
      "send a message to Claude asking for a haiku about coding"
    ],
    "token-counting": [
      "test anthropic connection",
      "count how many tokens are in the message 'Hello, how are you today?'"
    ],
    "batch-workflow": [
      "test anthropic connection",
      "list all message batches",
      "get the status of the first batch if any exist"
    ],
    "conversation": [
      "test anthropic connection",
      "ask Claude what is the capital of France",
      "ask Claude to tell me more about that city's history"
    ],
    "admin-organization": [
      "test admin connection",
      "get organization details",
      "list all organization members"
    ],
    "admin-workspaces": [
      "test admin connection",
      "list all workspaces",
      "create a new workspace called 'Development'"
    ],
    "admin-usage": [
      "test admin connection",
      "get usage report for the last 7 days",
      "get cost breakdown for last month"
    ],
    "admin-api-keys": [
      "test admin connection",
      "list all API keys",
      "show active API keys only"
    ]
  },
  "faq": [
    {
      "question": "How do I get an Anthropic API key?",
      "answer": "Sign up at https://console.anthropic.com and create an API key in the API Keys section."
    },
    {
      "question": "How do I get an Admin API key?",
      "answer": "Only organization admins can create Admin API keys at https://console.anthropic.com/settings/admin-keys. Admin keys start with sk-ant-admin... and enable organization/workspace management."
    },
    {
      "question": "What's the difference between regular and admin API keys?",
      "answer": "Regular API keys (ANTHROPIC_API_KEY) are for using Claude AI models. Admin API keys (ANTHROPIC_ADMIN_API_KEY) are for managing your organization, workspaces, members, and accessing usage/cost reports."
    },
    {
      "question": "What models are available?",
      "answer": "Claude 3.5 Sonnet (claude-3-5-sonnet-20241022), Claude 3 Opus (claude-3-opus-20240229), Claude 3 Haiku (claude-3-haiku-20240307), and more."
    },
    {
      "question": "What is the Messages API?",
      "answer": "The Messages API is the primary way to interact with Claude. It supports multi-turn conversations, tool use, images, and streaming."
    },
    {
      "question": "What are message batches?",
      "answer": "Message Batches allow you to process multiple messages asynchronously. Create a batch, poll for completion, then retrieve results."
    },
    {
      "question": "What can I do with the Admin API?",
      "answer": "Manage organization members and roles, create/manage workspaces, send invitations, monitor API keys, and access detailed usage/cost reports for billing and analytics."
    },
    {
      "question": "How do I format messages for the API?",
      "answer": "Messages should be a JSON array with objects containing 'role' (user/assistant) and 'content' (string or array of content blocks)."
    },
    {
      "question": "What is the max_tokens parameter?",
      "answer": "max_tokens specifies the maximum number of tokens Claude can generate in its response. Different models have different limits."
    }
  ],
  "scripts": {
    "build": "pets build",
    "generate": "pets generate-openapi --verbose",
    "quickstart": "pets exec anthropic-test-connection --plugin ./index.ts --args '{}' --json",
    "test:connection": "pets exec anthropic-test-connection --plugin ./index.ts --args '{}' --json",
    "test:all": "pets exec anthropic-test-connection --plugin ./index.ts --args '{}' --json"
  },
  "dependencies": {
    "openpets-sdk": "^1.0.0",
    "dotenv": "^16.0.0"
  },
  "openapiSpec": {
    "url": "https://raw.githubusercontent.com/laszukdawid/anthropic-openapi-spec/main/hosted_spec_v3.0.0.json",
    "baseUrl": "https://api.anthropic.com",
    "authType": "apiKey",
    "apiKeyHeader": "x-api-key",
    "authEnvVar": "ANTHROPIC_API_KEY",
    "coreEndpoints": {
      "paths": [
        "/v1/messages",
        "/v1/messages/count_tokens"
      ]
    },
    "exclude": [
      "complete"
    ]
  },
  "publishConfig": {
    "access": "public"
  },
  "files": [
    "index.ts",
    "index.js",
    "client.ts",
    "client.js",
    "*.d.ts",
    "lib/**/*",
    "src/**/*",
    "commands.json",
    "public/**/*",
    "prompts/**/*",
    "README.md"
  ]
}

import { config as loadDotenv } from "dotenv"
import { z, createPlugin, type ToolDefinition, loadEnv, createLogger } from "openpets-sdk"
import openAPITools from "./openapi-tools"
import adminTools from "./admin-tools"
import skillsTools from "./skills-tools"
import { isAdminConfigured } from "./admin-client"

loadDotenv()

export const AnthropicPlugin = async () => {
  const logger = createLogger("anthropic")
  const env = loadEnv("anthropic")

  const API_KEY = process.env.ANTHROPIC_API_KEY
  const ADMIN_KEY = process.env.ANTHROPIC_ADMIN_API_KEY
  const isConfigured = !!API_KEY
  const hasAdminAccess = !!ADMIN_KEY

  if (!isConfigured) {
    logger.warn("Anthropic plugin not configured - returning limited toolset")
    return createPlugin([
      {
        name: "anthropic-test-connection",
        description: "Test Anthropic API connection and configuration status",
        schema: z.object({}),
        async execute() {
          return JSON.stringify({
            success: false,
            status: "not_configured",
            message: "Anthropic plugin is not configured. Please set ANTHROPIC_API_KEY environment variable.",
            details: {
              error: "Missing required configuration",
              requiredVariables: ["ANTHROPIC_API_KEY"],
              optionalVariables: ["ANTHROPIC_ADMIN_API_KEY"],
              setupUrl: "https://console.anthropic.com/settings/keys",
              adminSetupUrl: "https://console.anthropic.com/settings/admin-keys"
            }
          }, null, 2)
        }
      }
    ])
  }

  logger.info("Initializing Anthropic plugin", {
    configured: true,
    adminAccess: hasAdminAccess
  })

  const allTools = [...openAPITools, ...skillsTools]

  if (hasAdminAccess) {
    logger.info("Admin API key detected - enabling admin tools")
    allTools.push(...adminTools)
  } else {
    logger.info("No admin API key - admin tools disabled (set ANTHROPIC_ADMIN_API_KEY to enable)")
    allTools.push({
      name: "anthropic-admin-test-connection",
      description: "Test Admin API connection (requires ANTHROPIC_ADMIN_API_KEY)",
      schema: z.object({}),
      async execute() {
        return JSON.stringify({
          success: false,
          status: "not_configured",
          message: "Admin API not configured. Set ANTHROPIC_ADMIN_API_KEY to enable admin features.",
          adminToolsAvailable: false,
          setupUrl: "https://console.anthropic.com/settings/admin-keys"
        }, null, 2)
      }
    })
  }

  return createPlugin(allTools)
}

export default AnthropicPlugin
